package com.scriptles.cabinet.profile.repository;
import com.scriptles.cabinet.profile.entity.HQProfile; import com.scriptles.cabinet.profile.enums.HQClaimStatus; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.Optional; import java.util.UUID;
public interface HQProfileRepository extends JpaRepository<HQProfile,UUID> { Optional<HQProfile> findByProfileId(UUID profileId); Optional<HQProfile> findByProfileHandleIgnoreCase(String handle); Optional<HQProfile> findByExternalSourceAndExternalId(String source, String externalId); long countByClaimStatus(HQClaimStatus status); @Query("select h from HQProfile h join fetch h.profile p where lower(p.handle) like lower(concat('%',:q,'%')) or lower(p.displayName) like lower(concat('%',:q,'%')) order by p.verified desc, lower(p.displayName)") Page<HQProfile> search(@Param("q") String q, Pageable pageable); }
